    &Methods;







   पूर्वपरिभाषित iterators
   दैनिक कार्यहरूका लागि PHP ले पहिले नै थुप्रै iterators उपलब्ध गराएको छ। list का लागि SPL iterators हेर्नुहोस्।




   &reftitle.examples;

    आधारभूत प्रयोग

यस उदाहरणले iterator सँग &foreach; प्रयोग गर्दा methods कुन क्रममा call हुन्छन् भन्ने देखाउँछ।


<?php
class myIterator implements Iterator {
    private $position = 0;
    private $array = array(
        "firstelement",
        "secondelement",
        "lastelement",
    );  

    public function __construct() {
        $this->position = 0;
    }

    public function rewind(): void {
        var_dump(__METHOD__);
        $this->position = 0;
    }

    #[\ReturnTypeWillChange]
    public function current() {
        var_dump(__METHOD__);
        return $this->array[$this->position];
    }

    #[\ReturnTypeWillChange]
    public function key() {
        var_dump(__METHOD__);
        return $this->position;
    }

    public function next(): void {
        var_dump(__METHOD__);
        ++$this->position;
    }

    public function valid(): bool {
        var_dump(__METHOD__);
        return isset($this->array[$this->position]);
    }
}

$it = new myIterator;

foreach($it as $key => $value) {
    var_dump($key, $value);
    echo "\n";
}
?>


